face.layout_source:
// fft_block_echo.face: the panel for tap/examples/spectral/fft_block_echo.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/fft_block_echo.face --meta <graph>.cragmeta

face "FFT Block Echo" {
  row(gap = 10) {
    box "Echo" { knob.big "Feedback" (feedback) }
    box "Mix" { vslider "Wet" (wet_level) vslider "Dry" (dry_level) }
    viz(grow = 1)
  }
}
